def taster_page(S):
    """A picture of the free taster page: a printed daily page with a name,
    a short list and an energy battery (the real one is drawn in the browser)."""
    pg = Image.new("RGB", (S, S), (233, 228, 214))
    d = ImageDraw.Draw(pg)
    m = 70
    d.rounded_rectangle((m, m, S - m, S - m), radius=18, fill=(255, 253, 248), outline=(214, 205, 186), width=3)
    d.text((m + 50, m + 46), "Today, for Sam", font=font("Fraunces-var.ttf", 52, 600), fill=BROWN)
    d.text((m + 52, m + 116), "one thing at a time", font=font("Caveat-var.ttf", 40, 600), fill=GREEN)
    y = m + 200
    for w in (300, 250, 280, 210, 240):
        d.rounded_rectangle((m + 52, y, m + 86, y + 34), radius=6, outline=INK, width=3)
        d.rounded_rectangle((m + 110, y + 12, m + 110 + w, y + 22), radius=5, fill=(196, 188, 170))
        y += 72
    bx, by = S - m - 190, m + 210
    d.text((bx - 6, by - 50), "battery", font=font("SpaceGrotesk-var.ttf", 26, 600), fill=GREEN)
    d.rounded_rectangle((bx, by, bx + 120, by + 260), radius=14, outline=INK, width=4)
    d.rectangle((bx + 40, by - 14, bx + 80, by), fill=INK)
    for k in range(3):
        d.rounded_rectangle((bx + 14, by + 172 - k * 78, bx + 106, by + 244 - k * 78), radius=8, fill=(143, 183, 132))
    d.line((m + 52, S - m - 140, S - m - 52, S - m - 140), fill=(214, 205, 186), width=2)
    d.text((m + 52, S - m - 116), "don't forget: water, meds, reply to Jo", font=font("Caveat-var.ttf", 38, 500), fill=BROWN)
    return pg


def font(name, size, weight=None):
    f = ImageFont.truetype(os.path.join(FONTS, name), size)
    if weight is not None:
        axes = f.get_variation_axes(); vals = [a.get("default", a["minimum"]) for a in axes]
        for i, a in enumerate(axes):
            n = a.get("name", ""); n = (n.decode() if isinstance(n, bytes) else str(n)).lower()
            if "weight" in n: vals[i] = weight
            elif "optical" in n: vals[i] = max(a["minimum"], min(a["maximum"], round(size * 0.75)))
        f.set_variation_by_axes(vals)
    return f


def centred(d, y, text, f, fill, spacing=0):
    if spacing:
        total = sum(d.textlength(c, font=f) for c in text) + spacing * (len(text) - 1)
        x = (W - total) / 2
        for c in text:
            d.text((x, y), c, font=f, fill=fill); x += d.textlength(c, font=f) + spacing
        return
    d.text(((W - d.textlength(text, font=f)) / 2, y), text, font=f, fill=fill)


def pin(p):
    img = Image.new("RGB", (W, H), CREAM)
    d = ImageDraw.Draw(img)
    centred(d, 78, p["kicker"], font("SpaceGrotesk-var.ttf", 26, 700), RED, spacing=3)
    centred(d, 130, p.get("head", "Socially Hibernating"), font("Fraunces-var.ttf", 92, 600), BROWN)
    # The product, on a white card with a soft shadow.
    S, x, y = 840, 80, 290
    if p.get("draw") == "taster":
        photo = taster_page(S)
    elif p["img"][0] == G:  # a 2x2 grid of product photos from /feed-images/
        photo = Image.new("RGB", (S, S), (255, 255, 255))
        t = (S - 12) // 2
        for k, name in enumerate(p["img"][1]):
            src = os.path.join(SETS, "set-uk.jpg") if name == "SET" else os.path.join(ROOT, "feed-images", name + ".jpg")
            tile = Image.open(src).convert("RGB")
            side = min(tile.size); tile = tile.crop(((tile.width - side) // 2, (tile.height - side) // 2, (tile.width + side) // 2, (tile.height + side) // 2))
            photo.paste(tile.resize((t, t), Image.LANCZOS), ((k % 2) * (t + 12), (k // 2) * (t + 12)))
    elif p["img"][0] == "OG":  # a product page's own 1200x1200 share picture
        photo = Image.open(os.path.join(ROOT, "p", p["img"][1], "og.png")).convert("RGB").resize((S, S), Image.LANCZOS)
    else:
        photo = Image.open(os.path.join(*p["img"])).convert("RGB").resize((S, S), Image.LANCZOS)
    sh = Image.new("L", (S + 80, S + 80), 0)
    ImageDraw.Draw(sh).rectangle((40, 40, 40 + S, 40 + S), fill=80)
    img.paste((60, 50, 40), (x - 40, y - 28), sh.filter(ImageFilter.GaussianBlur(18)))
    img.paste(photo, (x, y))
    d = ImageDraw.Draw(img)
    l1, l2 = p["lines"]
    centred(d, 1188, l1, font("Fraunces-var.ttf", 50, 600), INK)
    centred(d, 1256, l2, font("Fraunces-var.ttf", 44, 400), GREEN)
    d.line((W / 2 - 60, 1350, W / 2 + 60, 1350), fill=BROWN, width=3)
    centred(d, 1376, "Frog Logic", font("Caveat-var.ttf", 64, 700), BROWN)
    img.save(os.path.join(OUT, p["slug"] + ".jpg"), quality=88, optimize=True)


def main():
    os.makedirs(OUT, exist_ok=True)
    from datetime import date, timedelta
    day0 = date.fromisoformat(START)
    rows = []
    for i, p in enumerate({"1": PINS, "2": PINS2, "guides": PINS3, "gifts": PINS4, "help": PINS5}[BATCH]):
        pin(p)
        when = f"{(day0 + timedelta(days=i // len(SLOTS))).isoformat()}T{SLOTS[i % len(SLOTS)]}"
        rows.append([p["title"][:100], RAW + p["slug"] + ".jpg", p.get("board", BOARD), "", p["desc"][:500], p["link"], when, p["keys"]])
        print("made", p["slug"], when)
    with open(os.path.join(OUT, "xmas-pins.csv"), "w", newline="", encoding="utf-8") as f:
        w = csv.writer(f, quoting=csv.QUOTE_ALL)
        w.writerow(["Title", "Media URL", "Pinterest board", "Thumbnail", "Description", "Link", "Publish date", "Keywords"])
        w.writerows(rows)


if __name__ == "__main__":
    main()
